package com.nook.widgets;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.view.View;
import android.widget.RemoteViews;
import org.json.*;
import java.util.*;

/** Native launcher-side frame animation, slideshows and a video entry point. */
public final class MediaWidgets {
    private MediaWidgets(){}
    public static boolean supports(String kind){return kind.equals("animation")||kind.equals("slideshow")||kind.equals("video");}
    public static String[] variants(String kind){return kind.equals("animation")?new String[]{"Liquid orbit","Soft pulse","Ripple","Dot wave"}:kind.equals("slideshow")?new String[]{"Soft fade","Direct cut"}:new String[]{"Full video · silent inline","Still poster","Short loop · silent inline"};}
    public static int interval(JSONObject config){return new int[]{120,200,320}[WidgetDesign.clamp(config.optInt("motionSpeed",1),0,2)];}
    public static PendingIntent action(Context c,int id,String op){return PendingIntent.getBroadcast(c,0,new Intent(c,WidgetActionReceiver.class).setAction("motion_action").putExtra("widget",id).putExtra("op",op).setData(Uri.parse("nook://motion/"+id+"/"+op)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    public static PendingIntent play(Context c,int id,boolean floating){return PendingIntent.getActivity(c,0,new Intent(c,VideoPlayerActivity.class).putExtra("widget",id).putExtra("floating",floating).setData(Uri.parse("nook://video/"+id+"/"+floating)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    public static RemoteViews render(Context c,int id,String kind,JSONObject config,boolean small,boolean preview){
        boolean compact=small||config.optInt("density",0)==1||WidgetDesign.size(c,id,kind,config,small)[1]<220;RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,"widget_motion"+(compact?"_compact":""),config));WidgetDesign.Colors colors=WidgetDesign.colors(config,kind);
        int[] hidden={R.id.widget_title,R.id.widget_body,R.id.widget_meta,R.id.widget_time,R.id.widget_date,R.id.widget_progress,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2,R.id.tool_visual,R.id.tool_clocks,R.id.extra_chrono};for(int view:hidden)v.setViewVisibility(view,View.GONE);
        for(int text:new int[]{R.id.widget_title,R.id.widget_label,R.id.widget_settings,R.id.widget_body})v.setTextColor(text,colors.text);v.setInt(R.id.widget_icon,"setColorFilter",colors.accent);
        v.setTextViewText(R.id.widget_label,config.optString("title","").isEmpty()?Widgets.title(kind):config.optString("title"));v.setImageViewResource(R.id.widget_icon,Widgets.iconResource(kind));v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,kind));for(int n=0;n<3;n++)v.setImageViewResource(Widgets.BACKGROUND_IMAGES[n+1],Widgets.chipResource(config,kind));for(int bg:Widgets.BACKGROUND_IMAGES)v.setInt(bg,"setImageAlpha",Widgets.surfaceAlpha(config));
        v.setViewVisibility(R.id.media_stage,View.VISIBLE);v.removeAllViews(R.id.media_stage);v.setViewVisibility(R.id.widget_meta,View.VISIBLE);v.setTextColor(R.id.widget_meta,colors.muted);
        List<Bitmap> frames=new ArrayList<>();boolean paused=config.optBoolean("motionPaused",false),animate=!paused;int delay=interval(config),selected=0;String caption;
        if(kind.equals("animation")){for(int n=0;n<(paused?1:16);n++)frames.add(MediaData.scene(config,n,16));caption=variants(kind)[WidgetDesign.clamp(config.optInt("variant",0),0,3)]+(paused?" · Paused":" · Looping");}
        else if(kind.equals("slideshow")){List<String> photos=MediaData.photos(config);for(String uri:photos){Bitmap image=WidgetData.photo(c,uri);if(image!=null)frames.add(MediaData.fit(image,320,180,config.optBoolean("slideCrop",true),colors.surface));}selected=frames.isEmpty()?0:Math.floorMod(config.optInt("slideIndex",0),frames.size());delay=WidgetDesign.clamp(config.optInt("slideSeconds",5),2,60)*1000;caption=frames.isEmpty()?"Choose up to six photos":frames.size()+" photos · "+(paused?"Paused":delay/1000+"s each");}
        else{JSONObject info=MediaData.cached(c,config);int count=WidgetDesign.clamp(info.optInt("count",0),0,MediaData.MAX_FRAMES);animate=animate&&config.optInt("variant",0)==0;for(int n=0;n<(animate?count:Math.min(1,count));n++){Bitmap frame=MediaData.frame(c,config,info,n);if(frame!=null)frames.add(frame);}delay=info.optInt("interval",200);caption=frames.isEmpty()?(MediaData.document(config.optString("videoUri"))?"Update this segment in Options · Play is ready":"Choose a video and prepare its preview"):animate?"Silent "+String.format(Locale.getDefault(),"%.1fs",info.optLong("span")/1000f)+" loop · Tap to play":"Video poster · Tap to play";}
        if(frames.isEmpty()){v.setViewVisibility(R.id.widget_title,compact?View.GONE:View.VISIBLE);v.setTextViewText(R.id.widget_title,kind.equals("video")?"A little window for video":"Your moments, in motion");Bitmap placeholder=MediaData.scene(config,0,16);frames.add(placeholder);animate=false;}
        RemoteViews content;
        if(animate&&frames.size()>1||kind.equals("slideshow")&&!paused){content=new RemoteViews(c.getPackageName(),kind.equals("slideshow")&&frames.size()>1&&config.optInt("variant",0)==0?R.layout.motion_slideshow:R.layout.motion_sequence);content.setInt(R.id.motion_flipper,"setFlipInterval",Math.max(100,delay));content.removeAllViews(R.id.motion_flipper);for(Bitmap image:frames){RemoteViews child=new RemoteViews(c.getPackageName(),R.layout.motion_frame);child.setImageViewBitmap(R.id.motion_image,MediaData.widgetFrame(c,image,frames.size()));content.addView(R.id.motion_flipper,child);}content.setInt(R.id.motion_flipper,"setDisplayedChild",selected);}
        else{content=new RemoteViews(c.getPackageName(),R.layout.motion_frame);content.setImageViewBitmap(R.id.motion_image,MediaData.widgetFrame(c,frames.get(Math.min(selected,frames.size()-1)),1));}
        for(Bitmap b:frames)b.recycle();v.addView(R.id.media_stage,content);v.setTextViewText(R.id.widget_meta,caption);v.setContentDescription(R.id.media_stage,kind.equals("video")?"Video preview. Tap Play for full playback.":caption);
        String[] labels=kind.equals("video")?new String[]{"Play","Float","Options"}:new String[]{paused?"Resume":"Pause",kind.equals("slideshow")?"Next":"Change","Options"};int[] actions={R.id.widget_action0,R.id.widget_action1,R.id.widget_action2};v.setViewVisibility(R.id.widget_actions,View.VISIBLE);
        PendingIntent setup=LibraryWidgets.configure(c,id,kind);for(int n=0;n<3;n++){v.setTextViewText(actions[n],labels[n]);v.setTextColor(actions[n],colors.text);}if(!preview){v.setOnClickPendingIntent(R.id.widget_settings,setup);v.setOnClickPendingIntent(R.id.widget_root,kind.equals("video")&&MediaData.document(config.optString("videoUri"))?play(c,id,false):setup);v.setOnClickPendingIntent(actions[2],setup);v.setOnClickPendingIntent(actions[0],kind.equals("video")?(MediaData.document(config.optString("videoUri"))?play(c,id,false):setup):action(c,id,"toggle"));v.setOnClickPendingIntent(actions[1],kind.equals("video")?(MediaData.document(config.optString("videoUri"))?play(c,id,true):setup):action(c,id,kind.equals("slideshow")?"next":"change"));}
        WidgetDesign.surfaces(c,v,id,kind,config,compact,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});WidgetDesign.dedicated(c,v,id,kind,config,compact);v.setInt(R.id.widget_meta,"setMaxLines",1);if(compact&&(config.optBoolean("_embedded",false)||WidgetDesign.size(c,id,kind,config,small)[1]<170))v.setViewVisibility(R.id.widget_meta,View.GONE);return v;
    }
    public static void receive(Context c,int id,String op){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(info==null)return;String provider=Widgets.kindOf(info.provider);JSONObject root=Store.config(c,id);String kind=provider.equals("universal")?UniversalWidget.currentPage(root):provider;if(kind.equals("video")){VideoWidgets.receive(c,id,op);return;}if(!supports(kind))return;JSONObject config=provider.equals("universal")?UniversalWidget.pageSettings(root,kind):root;
        if("toggle".equals(op))ExtraData.put(config,"motionPaused",!config.optBoolean("motionPaused",false));else if("change".equals(op)&&kind.equals("animation"))ExtraData.put(config,"variant",Math.floorMod(config.optInt("variant",0)+1,4));else if("next".equals(op)&&kind.equals("slideshow"))ExtraData.put(config,"slideIndex",Math.floorMod(config.optInt("slideIndex",0)+1,Math.max(1,MediaData.photos(config).size())));else return;Store.config(c,id,root);if("next".equals(op)&&!config.optBoolean("motionPaused",false)){RemoteViews step=new RemoteViews(c.getPackageName(),provider.equals("universal")?R.layout.widget_universal:R.layout.widget_motion);step.showNext(R.id.motion_flipper);AppWidgetManager.getInstance(c).partiallyUpdateAppWidget(id,step);}else Widgets.update(c,id,provider);
    }
}
